styles.globalCss:
.hyperpbi-root{
  --ent-bg:#f3f6fa;
  --ent-panel:#ffffff;
  --ent-panel-soft:#f8fafc;
  --ent-line:#dce4ef;
  --ent-line-strong:#c8d4e3;
  --ent-text:#172033;
  --ent-muted:#66758a;
  --ent-primary:#2457d6;
  --ent-primary-soft:#edf3ff;
  --ent-teal:#0e7490;
  --ent-teal-soft:#e8f6f7;
  --ent-purple:#6d5bd0;
  --ent-success:#15803d;
  --ent-warning:#b45309;
  --ent-danger:#c2415d;
  width:100%;
  min-height:100%;
  color:var(--ent-text);
  background:
    radial-gradient(circle at 82% -12%,rgba(36,87,214,.08),transparent 34%),
    linear-gradient(180deg,#f8fafc 0%,#f3f6fa 42%,#eef3f8 100%);
  font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;
}
.hyperpbi-root *{box-sizing:border-box;scrollbar-width:thin;scrollbar-color:#c8d4e3 transparent}
.hyperpbi-root *::-webkit-scrollbar{width:7px;height:7px}
.hyperpbi-root *::-webkit-scrollbar-track{background:transparent}
.hyperpbi-root *::-webkit-scrollbar-thumb{border-radius:999px;background:#c8d4e3}

/* Application shell */
.hp-app-shell{background:transparent}
.hp-navbar{
  min-height:60px;padding:8px 15px;border-bottom:1px solid var(--ent-line);
  background:rgba(255,255,255,.96);backdrop-filter:blur(16px);
  box-shadow:0 3px 14px rgba(24,45,75,.05)
}
.hp-navbar-brand-icon{
  width:36px;height:36px;border-radius:10px;
  background:linear-gradient(145deg,#2457d6,#0e7490);
  color:#fff;box-shadow:0 7px 18px rgba(36,87,214,.20)
}
.hp-navbar-brand-title{color:#172033;font-size:14px;font-weight:780;letter-spacing:.055em}
.hp-navbar-brand-subtitle{color:#7b899d;font-size:9px}
.hp-navbar-search{max-width:400px}
.hp-navbar-search input{
  min-height:38px;border:1px solid var(--ent-line-strong);border-radius:10px;
  background:#f8fafc;color:var(--ent-text)
}
.hp-navbar-search input:focus{
  border-color:#7c9ce6;box-shadow:0 0 0 3px rgba(36,87,214,.10)
}
.hp-navbar-action,.hp-navbar-user-btn{
  border:1px solid transparent;border-radius:9px;color:#526176
}
.hp-navbar-action:hover,.hp-navbar-user-btn:hover{
  border-color:var(--ent-line);background:#f5f8fc;color:#172033
}
.hp-sidebar-app{
  width:224px;background:linear-gradient(180deg,#ffffff,#f8fafc);
  border-right:1px solid var(--ent-line);
  box-shadow:5px 0 18px rgba(24,45,75,.035)
}
.hp-sidebar-collapsed{width:68px}
.hp-app-nav{padding:13px 9px}
.hp-nav-item{
  position:relative;margin:3px 0;padding:10px 11px;border:1px solid transparent;
  border-radius:9px;color:#64748b;font-size:11px;font-weight:570
}
.hp-nav-item:hover{border-color:#d9e3ef;background:#fff;color:#172033}
.hp-nav-active{
  border-color:#c9d7f5;
  background:linear-gradient(90deg,#edf3ff,#f6f8ff);
  color:#2457d6;font-weight:700;
  box-shadow:0 4px 12px rgba(36,87,214,.06)
}
.hp-nav-active::before{
  left:4px;width:3px;height:22px;border-radius:999px;background:#2457d6
}
.hp-sidebar-footer{border-color:var(--ent-line)}
.hp-sidebar-footer-title{color:#334155}
.hp-sidebar-footer-subtitle{color:#94a3b8}
.hp-app-content{background:transparent}
.hp-page-header{padding:19px 19px 15px;border:0;background:transparent}
.hp-page-header-title{color:#172033;font-size:24px;font-weight:720;letter-spacing:-.035em}
.hp-page-header-subtitle{margin-top:5px;color:#66758a;font-size:11px}
.hp-breadcrumbs ol{color:#8492a5}
.hp-meta-item{
  border:1px solid #d6e0ec;background:#fff!important;color:#475569!important;
  box-shadow:0 2px 7px rgba(24,45,75,.035)
}
.hp-app-main{padding:4px 15px 22px;background:transparent}
.hp-app-main>.hp-grid{gap:12px}
.hp-app-footer{border-top:1px solid var(--ent-line);background:#f8fafc;color:#7b899d}

/* Toolbar, controls and tabs */
.hp-toolbar{
  margin:0 0 11px;padding:7px 10px;border:1px solid var(--ent-line);
  border-radius:11px;background:rgba(255,255,255,.88)
}
.hp-chips{border:0;background:transparent}
.hp-chip{border-color:#bfd0ef;background:#edf3ff;color:#2457d6}
.hp-tabs>.nav-tabs{
  display:flex;gap:4px;width:max-content;margin:0 0 13px;padding:4px;
  border:1px solid var(--ent-line);border-radius:11px;background:#fff;
  box-shadow:0 4px 14px rgba(24,45,75,.04)
}
.hp-tabs>.nav-tabs .nav-link{
  padding:8px 14px;border:0;border-radius:8px;color:#718096;font-size:10px;font-weight:680
}
.hp-tabs>.nav-tabs .nav-link:hover{background:#f5f8fc;color:#172033}
.hp-tabs>.nav-tabs .nav-link.active{
  background:#edf3ff;color:#2457d6;box-shadow:inset 0 0 0 1px #cbd9f7
}
.hp-tab-content{padding:0}
.hp-tab-content>.hp-grid{gap:12px}
.hp-control{gap:6px;color:#59687c;font-size:10px}
.hp-control input,.hp-control select{
  min-height:38px;border:1px solid var(--ent-line-strong);border-radius:9px;
  background:#fff;color:var(--ent-text)
}
.hp-control input:focus,.hp-control select:focus{
  border-color:#7c9ce6;box-shadow:0 0 0 3px rgba(36,87,214,.10)
}
.hp-button{
  min-height:36px;border:1px solid var(--ent-line-strong);border-radius:9px;
  background:#fff;color:#334155;font-size:10px;font-weight:680;
  box-shadow:0 2px 7px rgba(24,45,75,.04)
}
.hp-button:hover{border-color:#9bb2d4;background:#f7faff;color:#2457d6}
.hp-variant-primary{
  border-color:#2457d6!important;background:#2457d6!important;color:#fff!important;
  box-shadow:0 6px 14px rgba(36,87,214,.18)!important
}

/* Cards */
.hp-component{min-width:0}
.hp-card,.hp-custom,.hp-table-wrap,.hp-matrix-wrap{
  border:1px solid var(--ent-line);border-radius:12px;background:#fff;color:var(--ent-text);
  box-shadow:0 8px 24px rgba(24,45,75,.055)
}
.hp-card-header{min-height:46px;padding:12px 14px;border-color:#e6edf5}
.hp-card-header h3,.hp-card-title{
  color:#172033;font-size:12px;font-weight:720;letter-spacing:.005em
}
.hp-card-subtitle{color:#7a899d}
.hp-card-body{padding:12px}
.hp-custom-body{padding:0}
.hp-component-custom>.hp-custom{height:100%}
.hp-component-grid>.hp-grid{width:100%;margin:0;padding:0;border:0;background:transparent;box-shadow:none}
.hp-chart-warnings{display:none}

/* Hero */
[data-hp-id="hero_signal"]>.hp-custom{
  overflow:hidden;border-color:#cfdbeb;
  background:
    radial-gradient(circle at 90% 12%,rgba(36,87,214,.10),transparent 26%),
    radial-gradient(circle at 74% 82%,rgba(14,116,144,.08),transparent 25%),
    linear-gradient(135deg,#ffffff,#f6f9fd)
}
.aurora-hero{
  min-height:130px;display:grid;grid-template-columns:minmax(0,1.4fr) auto auto;
  align-items:center;gap:20px;padding:20px 22px
}
.aurora-kicker{
  display:flex;align-items:center;gap:8px;color:#0e7490;
  font-size:9px;font-weight:820;letter-spacing:.15em;text-transform:uppercase
}
.aurora-live-dot{
  width:8px;height:8px;border-radius:999px;background:#16a34a;
  box-shadow:0 0 0 5px rgba(22,163,74,.10)
}
.aurora-hero h2{margin:8px 0 5px;color:#172033;font-size:25px;font-weight:650;letter-spacing:-.035em}
.aurora-hero p{max-width:720px;margin:0;color:#66758a;font-size:11px;line-height:1.55}
.aurora-hero-stat{
  min-width:130px;padding:12px 14px;border:1px solid #d7e1ed;border-radius:11px;
  background:rgba(255,255,255,.88);box-shadow:0 5px 14px rgba(24,45,75,.045)
}
.aurora-hero-stat span{display:block;color:#7b899d;font-size:8px;text-transform:uppercase;letter-spacing:.11em}
.aurora-hero-stat strong{display:block;margin-top:7px;color:#172033;font-size:23px;font-weight:630}
.aurora-hero-stat small{display:block;margin-top:3px;color:#15803d;font-size:8px}

/* KPI grid */
[data-hp-id="executive_metrics"] .hp-metric-grid{
  grid-template-columns:repeat(5,minmax(0,1fr));gap:10px
}
[data-hp-id="executive_metrics"] .hp-metric{
  position:relative;min-height:112px;padding:15px;border:1px solid #dbe4ef;border-left:1px solid #dbe4ef;
  border-radius:11px;background:linear-gradient(155deg,#ffffff,#f8fafc);overflow:hidden;
  box-shadow:0 7px 18px rgba(24,45,75,.045)
}
[data-hp-id="executive_metrics"] .hp-metric::after{
  content:"";position:absolute;right:-28px;bottom:-35px;width:90px;height:90px;border-radius:999px;
  background:radial-gradient(circle,rgba(36,87,214,.10),transparent 68%)
}
[data-hp-id="executive_metrics"] .hp-metric-label{
  color:#718096;font-size:9px;letter-spacing:.075em;text-transform:uppercase
}
[data-hp-id="executive_metrics"] .hp-metric-value{
  margin-top:12px;color:#172033;font-size:26px;font-weight:680;letter-spacing:-.035em
}
[data-hp-id="executive_metrics"] .hp-metric:nth-child(1){box-shadow:inset 0 3px 0 #0e7490,0 7px 18px rgba(24,45,75,.045)}
[data-hp-id="executive_metrics"] .hp-metric:nth-child(2){box-shadow:inset 0 3px 0 #2457d6,0 7px 18px rgba(24,45,75,.045)}
[data-hp-id="executive_metrics"] .hp-metric:nth-child(3){box-shadow:inset 0 3px 0 #c2415d,0 7px 18px rgba(24,45,75,.045)}
[data-hp-id="executive_metrics"] .hp-metric:nth-child(4){box-shadow:inset 0 3px 0 #6d5bd0,0 7px 18px rgba(24,45,75,.045)}
[data-hp-id="executive_metrics"] .hp-metric:nth-child(5){box-shadow:inset 0 3px 0 #b45309,0 7px 18px rgba(24,45,75,.045)}

/* Map */
[data-hp-id="globalmap"] .hp-card{overflow:hidden}
[data-hp-id="globalmap"] .hp-card-body{padding:0}
[data-hp-id="globalmap"] .hp-map-container{border-radius:0 0 12px 12px}
[data-hp-id="globalmap"] .leaflet-control-zoom a,
[data-hp-id="globalmap"] .leaflet-control-layers,
[data-hp-id="globalmap"] .hp-map-toolbar{
  border-color:#d4deea!important;background:#fff!important;color:#334155!important
}
[data-hp-id="globalmap"] .leaflet-popup-content-wrapper,
[data-hp-id="globalmap"] .leaflet-popup-tip{background:#fff;color:#172033}

/* AI brief */
[data-hp-id="overview_side"]>.hp-grid{height:100%;align-content:start}
[data-hp-id="ai_brief_card"]>.hp-custom{
  border-color:#c5d9df;
  background:linear-gradient(145deg,#f0fbfb,#f5f3ff)
}
.ai-brief{padding:15px}
.ai-brief-head{display:flex;align-items:center;justify-content:space-between}
.ai-brief-head strong{color:#172033;font-size:11px}
.ai-brief-badge{
  padding:5px 8px;border:1px solid #a7ced5;border-radius:999px;
  background:#fff;color:#0e7490;font-size:8px
}
.ai-brief h3{margin:16px 0 7px;color:#172033;font-size:18px;line-height:1.25;font-weight:620;letter-spacing:-.02em}
.ai-brief p{margin:0;color:#66758a;font-size:9px;line-height:1.55}
.ai-brief ul{margin:13px 0 0;padding:0;list-style:none}
.ai-brief li{display:flex;gap:8px;padding:7px 0;border-top:1px solid rgba(99,130,148,.16);color:#475569;font-size:9px}
.ai-brief li::before{content:"◆";color:#0e7490;font-size:7px;margin-top:2px}


/* Enterprise architecture */
[data-hp-id="architecture_intro"]>.hp-custom{
  overflow:hidden;
  border-color:#cbd9ec;
  background:
    radial-gradient(circle at 88% 10%,rgba(36,87,214,.10),transparent 28%),
    radial-gradient(circle at 72% 94%,rgba(14,116,144,.08),transparent 30%),
    linear-gradient(135deg,#ffffff,#f5f8fc);
}
.architecture-intro{
  min-height:126px;
  display:grid;
  grid-template-columns:minmax(0,1fr) repeat(3,130px);
  align-items:center;
  gap:14px;
  padding:19px 21px;
}
.architecture-kicker{
  display:block;
  color:#2457d6;
  font-size:9px;
  font-weight:820;
  letter-spacing:.14em;
}
.architecture-intro h2{
  margin:7px 0 5px;
  color:#172033;
  font-size:23px;
  font-weight:680;
  letter-spacing:-.03em;
}
.architecture-intro p{
  max-width:720px;
  margin:0;
  color:#66758a;
  font-size:10px;
  line-height:1.55;
}
.architecture-stat{
  padding:12px 13px;
  border:1px solid #d7e1ed;
  border-radius:10px;
  background:rgba(255,255,255,.90);
  box-shadow:0 4px 12px rgba(24,45,75,.04);
}
.architecture-stat span{
  display:block;
  color:#7b899d;
  font-size:8px;
  text-transform:uppercase;
  letter-spacing:.08em;
}
.architecture-stat strong{
  display:block;
  margin-top:7px;
  color:#172033;
  font-size:23px;
  font-weight:700;
}
[data-hp-id="operating_model_steps"]{
  padding:4px 0 2px;
}
[data-hp-id="architecture_portfolio"] .hp-card,
[data-hp-id="architecture_network"] .hp-card{
  border-top:3px solid #2457d6;
}
[data-hp-id="architecture_matrix"] .hp-card,
[data-hp-id="regional_councils"] .hp-card{
  border-top:3px solid #0e7490;
}
[data-hp-id="architecture_events"] .hp-table-wrap{
  border-top:3px solid #6d5bd0;
}

/* Table, matrix and lists */
.hp-list-group{border:0;background:transparent}
.hp-list-group-item{border-color:#e4ebf3;background:transparent;color:#334155}
.hp-list-group-item:hover{background:#f7f9fc}
.hp-list-group-primary{font-size:10px;font-weight:680}
.hp-list-group-secondary{color:#7a899d;font-size:8px}
.hp-table-wrap{overflow:hidden}
.hp-table th{
  padding:10px 11px;border-color:#dce4ef;background:#f5f8fc;
  color:#64748b;font-size:9px;font-weight:780;letter-spacing:.06em;text-transform:uppercase
}
.hp-table td{padding:9px 11px;border-color:#e8eef5;color:#334155;font-size:10px}
.hp-table tbody tr:hover td{background:#f7faff}
.hp-table tbody tr.hp-row-selected td{background:#edf3ff}
.hp-table tbody tr.hp-row-selected td:first-child{box-shadow:inset 3px 0 0 #2457d6}
.hp-table .hp-badge{border-radius:999px}
.hp-matrix th{background:#f5f8fc;color:#64748b}
.hp-matrix td{border-color:#e2eaf3}
.hp-pagination button{border-color:#d4deea;background:#fff;color:#475569}

/* Timeline */
.hp-timeline{border-color:#d7e1ed}
.hp-timeline-item{border-color:#dfe7f0}
.hp-timeline-marker{background:#6d5bd0;box-shadow:0 0 0 5px rgba(109,91,208,.10)}
.hp-timeline-date{color:#7c8a9d}
.hp-timeline-title{color:#172033}

/* Risk action card */
[data-hp-id="risk_action_plan"]>.hp-custom{
  border-color:#e5c9d1;
  background:
    radial-gradient(circle at 92% 8%,rgba(194,65,93,.08),transparent 30%),
    linear-gradient(160deg,#fff,#fff8fa)
}
.risk-plan{padding:17px}
.risk-plan-tag{
  display:inline-flex;padding:5px 8px;border:1px solid #dfb8c2;
  border-radius:999px;background:#fff;color:#a62f4b;font-size:8px;font-weight:740
}
.risk-plan h3{margin:15px 0 8px;color:#172033;font-size:19px;font-weight:620;letter-spacing:-.025em}
.risk-plan p{margin:0;color:#66758a;font-size:9px;line-height:1.55}
.risk-plan-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.risk-plan-step{padding:10px;border:1px solid #dce4ef;border-radius:9px;background:#fff}
.risk-plan-step b{display:block;color:#334155;font-size:9px}
.risk-plan-step span{display:block;margin-top:4px;color:#7b899d;font-size:8px}

/* Overlays */
.hp-offcanvas,.hp-modal-content{border-color:#d4deea;background:#fff;color:#172033}
.hp-offcanvas-header,.hp-modal-header{border-color:#e0e7ef;background:#f8fafc}
.hp-offcanvas-body,.hp-modal-body{background:#fff}
.hp-data-grid{border-color:#dce4ef;background:#fff}
.hp-data-grid-item{border-color:#e5ecf3}
.hp-data-grid-label{color:#7a899d}
.hp-data-grid-value{color:#334155}
.aurora-modal-copy{padding:6px}
.aurora-modal-copy h3{margin:0 0 8px;color:#172033;font-size:18px}
.aurora-modal-copy p{margin:0;color:#66758a;font-size:10px;line-height:1.55}
.aurora-modal-points{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:15px}
.aurora-modal-point{padding:11px;border:1px solid #dce4ef;border-radius:9px;background:#f8fafc}
.aurora-modal-point strong{display:block;color:#172033;font-size:18px}
.aurora-modal-point span{display:block;margin-top:4px;color:#7b899d;font-size:8px}

@container (max-width:1100px){
  .architecture-intro{grid-template-columns:1fr repeat(2,130px)}
  .architecture-stat:last-child{display:none}
  [data-hp-id="executive_metrics"] .hp-metric-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .aurora-hero{grid-template-columns:1fr auto}
  .aurora-hero-stat:last-child{display:none}
}
@container (max-width:820px){
  .architecture-intro{grid-template-columns:1fr}
  .architecture-stat{display:none}
  .hp-sidebar-app{width:68px}
  .hp-sidebar-app .hp-nav-label,.hp-sidebar-footer{display:none}
  .hp-sidebar-app .hp-nav-item{justify-content:center}
  [data-hp-id="executive_metrics"] .hp-metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aurora-hero{grid-template-columns:1fr}
  .aurora-hero-stat{display:none}
}
@container (max-width:560px){
  .hp-app-main{padding:4px 8px 16px}
  .hp-page-header{padding:14px 10px 10px}
  .hp-page-header-title{font-size:20px}
  [data-hp-id="executive_metrics"] .hp-metric-grid{grid-template-columns:1fr}
  .aurora-hero{padding:16px}
  .aurora-hero h2{font-size:21px}
  .aurora-modal-points{grid-template-columns:1fr}
}


/* Footer removal: prevent stale preview shells from floating over content. */
.hp-app-footer,
.hp-sidebar-footer{
  display:none!important;
  height:0!important;
  min-height:0!important;
  padding:0!important;
  margin:0!important;
  border:0!important;
}

/* Enterprise Control Center */
[data-hp-id="control_intro"]>.hp-custom{
  overflow:hidden;
  border-color:#cbd9ec;
  background:
    radial-gradient(circle at 91% 8%,rgba(36,87,214,.12),transparent 28%),
    radial-gradient(circle at 72% 100%,rgba(14,116,144,.09),transparent 31%),
    linear-gradient(135deg,#ffffff,#f4f8fd);
}
.control-intro{
  min-height:132px;
  display:grid;
  grid-template-columns:minmax(0,1fr) 150px 150px;
  align-items:center;
  gap:14px;
  padding:20px 22px;
}
.control-kicker{
  display:block;
  color:#2457d6;
  font-size:9px;
  font-weight:840;
  letter-spacing:.15em;
}
.control-intro h2{
  margin:8px 0 5px;
  color:#172033;
  font-size:24px;
  font-weight:700;
  letter-spacing:-.035em;
}
.control-intro p{
  max-width:760px;
  margin:0;
  color:#66758a;
  font-size:10px;
  line-height:1.58;
}
.control-signal{
  padding:13px 14px;
  border:1px solid #d5e0ed;
  border-radius:10px;
  background:rgba(255,255,255,.91);
  box-shadow:0 6px 16px rgba(24,45,75,.05);
}
.control-signal span{
  display:block;
  color:#7b899d;
  font-size:8px;
  text-transform:uppercase;
  letter-spacing:.08em;
}
.control-signal strong{
  display:block;
  margin-top:7px;
  color:#172033;
  font-size:20px;
  font-weight:720;
}
.control-signal small{
  display:block;
  margin-top:4px;
  color:#a62f4b;
  font-size:8px;
}
[data-hp-id="control_action_bar"]{
  align-items:center;
  padding:7px 9px;
  border:1px solid #dce4ef;
  border-radius:11px;
  background:#fff;
  box-shadow:0 5px 14px rgba(24,45,75,.04);
}
[data-hp-id="control_countups"] .hp-count-up,
[data-hp-id="control_countups"] .hp-card{
  border-top:3px solid #2457d6;
}
[data-hp-id="command_workspace"]{
  min-height:980px;
}
[data-hp-id="command_geo_section"],
[data-hp-id="command_decision_section"]{
  min-width:0;
}
[data-hp-id="command_geo_section"]>.hp-section,
[data-hp-id="command_decision_section"]>.hp-section{
  height:100%;
}
[data-hp-id="controlmap"] .hp-card{
  border-top:3px solid #0e7490;
}
[data-hp-id="control_risk_scatter"] .hp-card{
  border-top:3px solid #2457d6;
}
[data-hp-id="command_accordion"]{
